</main></div><script>
document.querySelector('.admin-menu')?.addEventListener('click',()=>document.querySelector('.admin-sidebar')?.classList.toggle('open'));
const adminNotificationToggle=document.querySelector('.admin-notification-toggle');
const adminNotificationPanel=document.querySelector('.admin-notification-panel');
adminNotificationToggle?.addEventListener('click',()=>{const open=adminNotificationPanel.hidden;adminNotificationPanel.hidden=!open;adminNotificationToggle.setAttribute('aria-expanded',String(open))});
document.addEventListener('click',event=>{if(adminNotificationPanel&&!adminNotificationPanel.hidden&&!event.target.closest('.admin-notification-menu')){adminNotificationPanel.hidden=true;adminNotificationToggle?.setAttribute('aria-expanded','false')}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&adminNotificationPanel&&!adminNotificationPanel.hidden){adminNotificationPanel.hidden=true;adminNotificationToggle?.setAttribute('aria-expanded','false');adminNotificationToggle?.focus()}});
const adminThemeButton=document.querySelector('.admin-theme-toggle');
const renderAdminTheme=()=>{const dark=document.documentElement.dataset.adminTheme==='dark';if(adminThemeButton){adminThemeButton.innerHTML='<i class="fa-solid fa-'+(dark?'sun':'moon')+'"></i>';adminThemeButton.title=dark?'Switch to light mode':'Switch to dark mode';adminThemeButton.setAttribute('aria-label',adminThemeButton.title)}};
adminThemeButton?.addEventListener('click',()=>{const next=document.documentElement.dataset.adminTheme==='dark'?'light':'dark';document.documentElement.dataset.adminTheme=next;localStorage.setItem('travelIndiaAdminTheme',next);renderAdminTheme()});renderAdminTheme();
const directoryPages=['packages.php','hotels.php','meals.php','transports.php','trip-themes.php','customers.php','admins.php','notifications.php','inbox.php','reviews.php','cancellation-policies.php'];
if(directoryPages.includes(location.pathname.split('/').pop()))document.querySelectorAll('.panel').forEach(panel=>{const table=panel.querySelector(':scope > .table-wrap > table');if(!table||panel.querySelector('.search-form'))return;const rows=[...table.tBodies[0]?.rows||[]];if(!rows.length)return;const head=panel.querySelector(':scope > .panel-head')||panel.insertBefore(document.createElement('div'),panel.firstChild);head.classList.add('panel-head');if(!head.querySelector('h2'))head.insertAdjacentHTML('afterbegin','<h2>Directory</h2>');const form=document.createElement('form');form.className='search-form directory-tools';form.innerHTML='<label class="sr-only">Search this table</label><input type="search" placeholder="Search records"><button class="primary-btn" type="submit"><i class="fa-solid fa-magnifying-glass"></i> Search</button><button class="reset-btn" type="button"><i class="fa-solid fa-rotate-left"></i> Reset</button>';head.append(form);const input=form.querySelector('input');const reset=form.querySelector('.reset-btn');const pager=panel.querySelector('.pagination');const filter=()=>{const term=input.value.trim().toLowerCase();rows.forEach(row=>row.hidden=term!==''&&!row.textContent.toLowerCase().includes(term));if(pager)pager.hidden=term!==''};form.addEventListener('submit',event=>{event.preventDefault();filter()});input.addEventListener('input',filter);reset.addEventListener('click',()=>{input.value='';filter();input.focus()})});
<?php if(basename($_SERVER['PHP_SELF']??'')==='packages.php'&&isset($showForm)&&$showForm):?>
document.addEventListener('DOMContentLoaded',()=>{const description=document.querySelector('textarea[name="description"]')?.closest('label');if(!description)return;const label=document.createElement('label');label.className='wide';label.innerHTML='Places to visit <small>Enter 5 to 7 unique places separated by commas.</small><textarea name="visit_places" required placeholder="Place one, Place two, Place three, Place four, Place five"></textarea>';label.querySelector('textarea').value=<?php echo json_encode((string)($edit['visit_places']??''),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);?>;description.after(label)});
<?php endif;?>
</script><script src="../js/admin-table-pagination.js?v=1"></script></body></html>
